var numbers = [3, 56, 2, 48, 5];

// map builds the new array for you
const doubled = numbers.map(function (x) {
  return x * 2;
});

// forEach needs a manual array and push
const doubled2 = [];
numbers.forEach(function (x) {
  doubled2.push(x * 2);
});

const small = numbers.filter(function (num) {
  return num < 10;
}); // [3, 2, 5]

const total = numbers.reduce(function (accumulator, currentNumber) {
  return accumulator + currentNumber;
}); // 114

const firstBig = numbers.find(function (num) {
  return num > 10;
}); // 56

const firstBigIndex = numbers.findIndex(function (num) {
  return num > 10;
}); // 1

var numbers = [3, 56, 2, 48, 5];

// forEach: keep a running total yourself
let total = 0;
numbers.forEach(function (currentNumber) {
  total += currentNumber;
});

// reduce: the return value becomes the next accumulator
const sum = numbers.reduce(function (accumulator, currentNumber) {
  console.log("accumulator:", accumulator, "current:", currentNumber);
  return accumulator + currentNumber;
});
// logs 3/56, 59/2, 61/48, 109/5 -> sum is 114

